// Regression for the simulated fleet's existing-card follow-ups. The real queue,
// structured model contract and fake Telegram transport are exercised in isolation.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';
import { config } from '../src/config.js';
import { runAs } from '../src/context.js';
import { loadChat } from '../src/memory.js';
import { photoRequest } from '../src/turn.js';
import { M, mkItem, turnRig, installModelStub, restoreFetch } from './lib/turn-rig.js';

const old = { data: config.dataDir, logs: config.logDir, price: process.env.STAR_PRICE, raw: M.rawStructured };
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'existing-card-'));
config.dataDir = path.join(tmp, 'data'); config.logDir = path.join(tmp, 'logs');
process.env.STAR_PRICE = 'real'; M.rawStructured = true; installModelStub();
const photos = [
  mkItem('photo', '11111111-1111-4111-8111-111111111111', 'A woman in a blue dress beside a window.', {star_value:500}),
  mkItem('photo', '22222222-2222-4222-8222-222222222222', 'A woman in a red shirt in a garden.', {star_value:700}),
];
const failures:string[] = []; let checks = 0, n = 0;
const check = (label:string, f:()=>void) => { checks++; try { f(); } catch(e:any) { failures.push(`${label}: ${e.message}`); } };
const media = (rig:ReturnType<typeof turnRig>) => rig.tg.calls.filter(c => ['sendPaidMedia','sendPhoto','sendVideo'].includes(c.method));
const slots = () => M.bodies.at(-1)?.response_format?.json_schema?.schema?.properties?.selection?.enum;
const send = async (rig:ReturnType<typeof turnRig>, text:string, selection:string, reply:string, route:any) => {
  const before = M.requests, sent = media(rig).length;
  M.reply = JSON.stringify({selection,reply});
  await rig.fan(81,text,route);
  check(`one model call: ${text}`,()=>assert.equal(M.requests - before,1));
  return {row:rig.rows().at(-1),newMedia:media(rig).slice(sent),selection:slots(),body:M.bodies.at(-1)};
};
const fresh = () => {
  const rig = turnRig('simulated', `existing-card-${++n}`); rig.deps.catalogue = photos;
  (rig.deps as any).verifyPhoto = async (key:string, storagePath:string) => {
    const item = rig.deps.catalogue.find(it => it.key === key && it.storagePath === storagePath);
    return {photo:item ? {ok:true,item} : {ok:false,reason:'missing'},ownership:{ok:true,keys:new Set(),at:Date.now()}};
  };
  return rig;
};

try {
  for (const route of [{bcid:'business-81'},{}]) {
    {
      const rig=fresh();
      const offered=await send(rig,'fuck that sounds hot. what kinda pics have u got?','none','i dont have beach but i got a bed pic thatll do the trick',route);
      check('verbal bed-pic offer sends no card',()=>assert.equal(offered.newMedia.length,0));
      check('verbal bed-pic offer reaches chat history',()=>assert.deepEqual(offered.row.final,['i dont have beach but i got a bed pic thatll do the trick']));
      const priced=await send(rig,'fuck that sounds hot. how many stars is that bed pic gonna cost me?','none','thats 100 stars babe, bout 2 bucks. tap the card n telegram walks you through it',route);
      check('unsent item price gets the honest fixed answer',()=>assert.deepEqual(priced.row.final,['i havent sent a card for that yet']));
      check('unsent item price sends no card',()=>assert.equal(priced.newMedia.length,0));
      check('unsent item price records both factual corrections',()=>assert(priced.row.grounding?.some((x:any)=>x.claims.includes("item price must come from Telegram's card")) && priced.row.grounding?.some((x:any)=>x.claims.includes('item price answer has no verified card'))));
      for(const [question,reply] of [['is that bed pic 100 stars?','yeah thats 100 stars'],['is that bed pic $2?','yeah thats $2']]){
        const confirmed=await send(rig,question,'none',reply,route);
        check(`unsent item price confirmation is grounded: ${question}`,()=>assert.deepEqual(confirmed.row.final,['i havent sent a card for that yet']));
        check(`unsent item price confirmation sends no card: ${question}`,()=>assert.equal(confirmed.newMedia.length,0));
      }
      const tipped=await send(rig,'is 100 stars a good tip for that pic?','none','100 stars sounds amazing babe',route);
      check('a fan tip question is not rewritten as an item-price answer',()=>assert.deepEqual(tipped.row.final,['100 stars sounds amazing babe']));
      check('a fan tip question sends no card',()=>assert.equal(tipped.newMedia.length,0));
      rig.stop();
    }
    for (const question of ['Yes, I want to see that one','What is in the photo you just sent?',
      'How many Stars is that photo?','What does that photo cost?','How much is that one?',
      'What does it cost?','Can I unlock that one?']) {
      const rig = fresh();
      const first = await send(rig,'Can you send me a photo?','photo 1','here is the photo',route);
      check('initial card accepted',()=>assert.equal(first.newMedia.length,1));
      const prior = runAs(rig.slug,()=>loadChat(81).photo);
      check('first photo has acknowledged receipt',()=>assert.equal(prior?.status,'acknowledged'));
      const result = await send(rig,question,'none','the card is in the chat, tap it to unlock if u want to see it',route);
      check(`existing-card answer is text only: ${question}`,()=>assert.deepEqual(result.selection,['none']));
      check(`no new file: ${question}`,()=>assert.equal(result.newMedia.length,0));
      check(`prior photo unchanged: ${question}`,()=>assert.equal(runAs(rig.slug,()=>loadChat(81).photo?.key),prior?.key));
      check(`prior evidence shown: ${question}`,()=>assert(result.body.messages[0].content.includes('blue dress') || result.body.messages[0].content.includes('red shirt')));
      rig.stop();
    }
  }
  {
    const rig = fresh(), route={bcid:'business-81'};
    const first=await send(rig,'send a photo','photo 1','here is one',route);
    const second=await send(rig,'Can I have a different one','photo 1','here is a different photo',route);
    check('explicit new request still selects eligible photo',()=>assert.equal(second.newMedia.length,1));
    check('explicit new request selects new key',()=>assert.notEqual(second.row.selectedMedia?.key,first.row.selectedMedia?.key));
    const again=await send(rig,'send that same photo again','photo 1','same photo',route);
    check('explicit resend keeps the exact key',()=>assert.equal(again.row.selectedMedia?.key,second.row.selectedMedia?.key));
    check('explicit resend sends once',()=>assert.equal(again.newMedia.length,1));
    rig.stop();
  }
  {
    const rig=fresh(),route={bcid:'business-81'};
    await send(rig,'send me a photo','photo 1','here is one',route);
    const accepted=await send(rig,'Yes, I want to see that one','none','tap the card to unlock',route);
    const later=await send(rig,'How many Stars is that photo?','none','the card shows the price',route);
    check('multiple follow-ups remain text only',()=>assert.deepEqual(later.selection,['none']));
    check('multiple follow-ups keep receipt',()=>assert.equal(later.newMedia.length+accepted.newMedia.length,0));
    const changed=await send(rig,'can i get a new photo','photo 1','here is the next one',route);
    check('later new request still works',()=>assert.equal(changed.newMedia.length,1));
    rig.stop();
  }
  {
    const rig=fresh(),route={bcid:'business-81'};
    const first=await send(rig,'send a photo','photo 1','here is the photo',route);
    const isBlue=first.row.selectedMedia?.key===photos[0].key;
    const correct=isBlue?'blue dress':'red shirt', wrong=isBlue?'red shirt':'blue dress';
    const about=await send(rig,'What is in the photo you just sent?','none',`that photo shows my ${correct}`,route);
    check('accurate prior description survives',()=>assert(about.row.final.join(' ').includes(correct)));
    const invented=await send(rig,'What is in that photo?','none',`that photo shows my ${wrong}`,route);
    check('unsupported prior description is removed',()=>assert(!invented.row.final.join(' ').includes(wrong)));
    const other=await send(rig,'I want to talk about that movie','none','sure, which movie?',route);
    check('changed subject retains normal offer choices',()=>assert(other.selection.includes('photo 1')));
    const asked=await send(rig,'Can you send me that photo?','photo 1','same one',route);
    check('deictic exact send uses the prior file',()=>assert.equal(asked.row.selectedMedia?.key,first.row.selectedMedia?.key));
    check('deictic exact send has only one selection',()=>assert.deepEqual(asked.selection,['photo 1']));
    rig.stop();
  }
  {
    const rig=fresh();
    const missing=await send(rig,'How many Stars is that photo?','none','which card do u mean?',{bcid:'business-81'});
    check('no unverified prior can cause a new file',()=>assert.deepEqual(missing.selection,['none']));
    check('absent reference disclosed in prompt',()=>assert(missing.body.messages[0].content.includes('No verified previous')));
    check('absent reference sends no file',()=>assert.equal(missing.newMedia.length,0));
    rig.stop();
  }
  {
    // Trashy's legacy file was eligible for the first acknowledged card but had no visual description.
    const rig=fresh(), route={};
    rig.deps.catalogue=[mkItem('photo','33333333-3333-4333-8333-333333333333','',{star_value:1999})];
    const first=await send(rig,'Can you send me a photo?','photo 1','here is the card',route);
    check('blank-description initial file was acknowledged',()=>assert.equal(first.newMedia.length,1));
    const again=await send(rig,'Send that same photo again','photo 1','same card',route);
    check('blank-description exact resend has only its original file',()=>assert.deepEqual(again.selection,['photo 1']));
    check('blank-description exact resend preserves the file key',()=>assert.equal(again.row.selectedMedia?.key,first.row.selectedMedia?.key));
    check('blank-description exact resend sends once',()=>assert.equal(again.newMedia.length,1));
    check('blank-description resend retains the paid price',()=>assert.equal(again.row.selectedMedia?.stars,1999));
    const unavailable=await send(rig,'Send that same photo again in a bikini','none','i cannot verify that detail',route);
    check('blank-description file cannot satisfy a specific visible request',()=>assert.deepEqual(unavailable.selection,['none']));
    check('unverified specific detail sends no file',()=>assert.equal(unavailable.newMedia.length,0));
    rig.stop();
  }
  {
    const rig=fresh(),route={bcid:'business-81'};
    await send(rig,'send me a photo','photo 1','here is the photo',route);
    const wrong=await send(rig,'How many Stars is that photo?','photo 1','here is another photo',route);
    check('out-of-contract model choice cannot send another card',()=>assert.equal(wrong.newMedia.length,0));
    check('out-of-contract model choice is recorded as failure',()=>assert.equal(wrong.row.note,'ai-failed'));
    rig.reset(81);
    const after=await send(rig,'What does that photo cost?','none','which card do u mean?',route);
    check('reset has no previous photo selection',()=>assert.deepEqual(after.selection,['none']));
    check('reset cannot use old card evidence',()=>assert(!after.body.messages[0].content.includes('Previous photo Telegram accepted')));
    rig.stop();
  }
  {
    const rig=fresh();
    await send(rig,'send me a photo','photo 1','here is a photo',{bcid:'business-81'});
    const crossed=await send(rig,'What is in that photo?','none','which card do u mean?',{bcid:'different-business'});
    check('another route cannot use previous card',()=>assert.deepEqual(crossed.selection,['none']));
    check('another route receives no prior description',()=>assert(!crossed.body.messages[0].content.includes('PREVIOUS PHOTO')));
